oauthDeclarations.BeginAuthorizationOptions:
interface BeginAuthorizationOptions {
    clientId: string;
    clientName?: string;
    redirectUri: string;
    scopes: OAuthScope[];
    portalUrl?: string;
}

oauthDeclarations.AuthorizationRequest:
interface AuthorizationRequest {
    url: string;
    codeVerifier: string;
    state: string;
}

oauthDeclarations.ExchangeCodeOptions:
interface ExchangeCodeOptions {
    baseUrl: string;
    code: string;
    codeVerifier: string;
    clientId: string;
    redirectUri: string;
    http?: HttpAdapter;
}

oauthDeclarations.CallbackResult:
interface CallbackResult {
    code?: string;
    state?: string;
    iss?: string;
    error?: string;
}

oauthDeclarations.parseCallback:
function parseCallback(callbackUrl: string): CallbackResult {
    const u = new URL(callbackUrl);
    const g = (k: string): string | undefined => u.searchParams.get(k) ?? undefined;
    return { code: g("code"), state: g("state"), iss: g("iss"), error: g("error") };
}

oauthDeclarations.beginAuthorization:
async function beginAuthorization(opts: BeginAuthorizationOptions): Promise<AuthorizationRequest> {
    const clientId = (opts.clientId ?? "").trim();
    if (!clientId) {
        throw new Error("beginAuthorization: clientId is required (register one in the Plum developer console)");
    }
    if (!opts.scopes || opts.scopes.length === 0) {
        throw new Error("beginAuthorization: at least one scope is required");
    }
    const portal = (opts.portalUrl ?? DEFAULT_PORTAL_URL).replace(/\/+$/, "");
    const codeVerifier = b64url(randomBytes(32));
    const codeChallenge = b64url(await sha256(new TextEncoder().encode(codeVerifier)));
    const state = b64url(randomBytes(16));
    const params = new URLSearchParams({
        response_type: "code",
        client_id: clientId,
        redirect_uri: opts.redirectUri,
        scope: opts.scopes.join(" "),
        code_challenge: codeChallenge,
        code_challenge_method: "S256",
        state,
    });
    if (opts.clientName)
        params.set("client_name", opts.clientName);
    return { url: `${portal}/authorize?${params}`, codeVerifier, state };
}

oauthDeclarations.exchangeCode:
async function exchangeCode(opts: ExchangeCodeOptions): Promise<{
    accessToken: string;
    scope: string;
}> {
    const http = opts.http ?? fetchAdapter;
    const res = await http.request({
        url: opts.baseUrl.replace(/\/+$/, "") + "/api/oauth/token",
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
            grant_type: "authorization_code",
            code: opts.code,
            code_verifier: opts.codeVerifier,
            client_id: opts.clientId,
            redirect_uri: opts.redirectUri,
        }),
    });
    if (res.status !== 200) {
        throw errorFromResponse(res.status, responseText(res));
    }
    const body = responseJSON<{
        access_token: string;
        scope: string;
    }>(res);
    return { accessToken: body.access_token, scope: body.scope };
}

oauthHelpers.b64url:
const b64url = (bytes: Uint8Array): string => {
    let s = "";
    for (const b of bytes)
        s += String.fromCharCode(b);
    return btoaShim(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
};

oauthHelpers.btoaShim:
function btoaShim(s: string): string {
    const g = globalThis as {
        btoa?: (s: string) => string;
        Buffer?: typeof Buffer;
    };
    if (typeof g.btoa === "function")
        return g.btoa(s);
    if (g.Buffer)
        return g.Buffer.from(s, "binary").toString("base64");
    throw new Error("no base64 encoder available");
}

oauthHelpers.randomBytes:
function randomBytes(n: number): Uint8Array {
    const g = globalThis as {
        crypto?: {
            getRandomValues?: (a: Uint8Array) => Uint8Array;
        };
    };
    const out = new Uint8Array(n);
    if (g.crypto?.getRandomValues)
        return g.crypto.getRandomValues(out);
    throw new Error("no secure RNG available");
}

oauthHelpers.sha256:
async function sha256(bytes: Uint8Array): Promise<Uint8Array> {
    const g = globalThis as {
        crypto?: Crypto;
    };
    let subtle = g.crypto?.subtle;
    if (!subtle) {
        const nodeCrypto = (await import("node:crypto")) as unknown as {
            webcrypto?: Crypto;
        };
        subtle = nodeCrypto.webcrypto?.subtle;
    }
    if (!subtle)
        throw new Error("no SubtleCrypto for PKCE");
    return new Uint8Array(await subtle.digest("SHA-256", bytes as unknown as BufferSource));
}

